//! The battery pill.
//!
//! The pill is an SVG regenerated by the shell whenever the drawing would
//! change. Its filename encodes capacity and charge state, so the path changes
//! exactly when the picture does — which is what makes eww and GTK reload it,
//! since new bytes at a cached path would not.

use crate::action::ActionKind;
use crate::config::Config;
use crate::ctx::{Ctx, Vars};
use crate::event::Probe;
use crate::model::Battery as Level;
use crate::widgets::{PollPlan, Widget};

#[derive(Clone, Debug, Default)]
pub struct Battery {
    level: Level,
    /// Set once the shell confirms the SVG for `level` exists on disk.
    rendered: bool,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Ev {
    Observed(Level),
    Rendered,
}

impl Battery {
    pub fn level(&self) -> Level {
        self.level
    }

    pub(crate) fn icon(&self, cfg: &Config) -> String {
        format!(
            "{}/battery-{}-{}.svg",
            cfg.cache_dir,
            self.level.percent,
            u8::from(self.level.charging)
        )
    }
}

impl Widget for Battery {
    type Ev = Ev;

    fn update(&mut self, ev: Ev, cx: &mut Ctx) {
        match ev {
            Ev::Observed(level) => {
                let level = Level {
                    percent: level.percent.min(100),
                    ..level
                };
                if level != self.level || !self.rendered {
                    self.level = level;
                    self.rendered = false;
                    cx.dispatch(ActionKind::RenderBattery {
                        percent: level.percent,
                        charging: level.charging,
                    });
                }
            }
            Ev::Rendered => self.rendered = true,
        }
    }

    fn vars(&self, cfg: &Config, out: &mut Vars) {
        out.set("batt_icon", self.icon(cfg));
        out.set("batt_pct", self.level.percent);
        out.set("batt_charging", self.level.charging);
    }

    fn polls(&self, cfg: &Config, out: &mut PollPlan) {
        out.insert(Probe::Battery, cfg.poll.battery);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_util::{kinds, run};

    #[test]
    fn redraws_only_when_the_picture_changes() {
        let mut b = Battery::default();
        let l = Level {
            percent: 55,
            charging: false,
        };
        assert_eq!(kinds(run(&mut b, Ev::Observed(l))).len(), 1);
        run(&mut b, Ev::Rendered);
        assert!(kinds(run(&mut b, Ev::Observed(l))).is_empty());
        assert_eq!(
            kinds(run(
                &mut b,
                Ev::Observed(Level {
                    percent: 55,
                    charging: true
                })
            ))
            .len(),
            1,
            "plugging in changes the fill colour"
        );
    }

    #[test]
    fn retries_until_the_shell_confirms() {
        let mut b = Battery::default();
        let l = Level {
            percent: 30,
            charging: false,
        };
        assert_eq!(kinds(run(&mut b, Ev::Observed(l))).len(), 1);
        assert_eq!(
            kinds(run(&mut b, Ev::Observed(l))).len(),
            1,
            "an unconfirmed render is attempted again"
        );
    }
}
